import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { createPrimitives } from '@/primitives';
import { createText } from '@/text';
import { uv, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container for this node
  const root = new Group();

  // Determine plane size based on source rect aspect (default fallback)
  const src = config.atlasRegion?.sourceRect || { width: 512, height: 320 };
  const aspect = src.width / src.height || 1.6;
  const planeWidth = aspect; // using 1 unit height
  const planeHeight = 1;

  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial();
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture asynchronously; material will be updated when ready
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Empty handlers object (no interactions defined)
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // Dispose texture if it was loaded
    if (loadedTexture && loadedTexture.dispose) {
      loadedTexture.dispose();
    }

    // Kill any GSAP timelines that might have been created (none in this node)
    gsap.globalTimeline.clear();
  };

  return root;
}
